from math import comb

def calculate_R_Kn(n):
    if n < 4:
        return None
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)

    if f_kn == 0:
        return None

    return (g_kn**3) / (f_kn**4)

# Test values up to N=20
results = {}
for n in range(4, 21):
    r = calculate_R_Kn(n)
    results[n] = r

print("R(K_N) values for N=4 to 20:")
for n, r in results.items():
    print(f"N={n}: R(K_{n}) = {r}")

# Check the asymptotic limit L = 3/32
L = 3/32
print(f"\nAsymptotic Limit L = 3/32 = {L}")
